#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    int a, b, c;
    cin >> a >> b >> c;
    int x, y, z;
    cin >> x >> y >> z;

    int min_sum = min(a, x + z) + min(b, y + x) + min(c, z + y);
    int max_sum = min(a, y) + min(b, z) + min(c, x);

    cout << n - min_sum << " " << max_sum << "\n";

    return 0;
}
